package com.hostelcheck.backend.controller;
import com.hostelcheck.backend.entity.*;import com.hostelcheck.backend.repository.*;import com.hostelcheck.backend.service.AuthService;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController @RequestMapping("/api") public class EngagementController {private final AuthService auth;private final PropertyListingRepository properties;private final InspectionRequestRepository inspections;private final FraudReportRepository reports;public EngagementController(AuthService a,PropertyListingRepository p,InspectionRequestRepository i,FraudReportRepository r){auth=a;properties=p;inspections=i;reports=r;}
 @PostMapping("/inspections") public Map<String,Object> inspection(@RequestHeader(value="X-Auth-Token",required=false)String token,@RequestBody Map<String,Object>d){UserAccount u=auth.require(token);if(!u.getRole().equals("Student"))throw new IllegalArgumentException("Only student accounts can request inspections.");Long pid=Long.valueOf(AuthService.str(d,"propertyId"));PropertyListing listing=properties.findById(pid).orElseThrow(()->new IllegalArgumentException("Property not found."));if(!listing.getStatus().equals("APPROVED"))throw new IllegalArgumentException("Inspection requests are only available for approved listings.");InspectionRequest r=new InspectionRequest();r.setPropertyId(pid);r.setStudentId(u.getId());r.setStudentName(u.getFullName());r.setStudentPhone(u.getPhone());r.setMessage(AuthService.str(d,"message"));r=inspections.save(r);return Map.of("id",r.getId(),"status",r.getStatus(),"message","Your inspection request has been submitted." );}
 @PostMapping("/fraud-reports") public Map<String,Object> report(@RequestHeader(value="X-Auth-Token",required=false)String token,@RequestBody Map<String,Object>d){UserAccount u=auth.require(token);String details=AuthService.str(d,"details");if(details.length()<10)throw new IllegalArgumentException("Please provide at least 10 characters describing the concern.");FraudReport r=new FraudReport();r.setReporterId(u.getId());r.setReporterEmail(u.getEmail());r.setDetails(details);if(!AuthService.str(d,"propertyId").isBlank())r.setPropertyId(Long.valueOf(AuthService.str(d,"propertyId")));r=reports.save(r);return Map.of("id",r.getId(),"status",r.getStatus(),"message","Thank you. Your report has been sent for review.");}
 @GetMapping("/my/inspections") public List<Map<String,Object>> myInspections(@RequestHeader(value="X-Auth-Token",required=false)String token){UserAccount u=auth.require(token);return inspections.findByStudentIdOrderByCreatedAtDesc(u.getId()).stream().map(r->Map.<String,Object>of("id",r.getId(),"propertyId",r.getPropertyId(),"status",r.getStatus(),"message",r.getMessage()==null?"":r.getMessage(),"createdAt",r.getCreatedAt())).toList();}
}
